import React, { memo } from 'react';
import { View, Text, TouchableOpacity, ScrollView } from 'react-native';
import { AOE_TYPES, AOE_SIZES } from '../constants';

export const AoeControls = memo(({ 
  aoeMode, 
  selectedAoe, 
  onTypeChange, 
  onSizeChange, 
  onToggle,
  styles 
}) => (
  <View style={styles.aoeControls}>
    <TouchableOpacity
      style={[styles.aoeButton, aoeMode && styles.aoeButtonActive]}
      onPress={onToggle}
    >
      <Text style={styles.aoeButtonText}>
        {aoeMode ? '🎯 AoE Active' : '🎯 AoE Mode'}
      </Text>
    </TouchableOpacity>
    
    {aoeMode && (
      <>
        <ScrollView 
          horizontal 
          showsHorizontalScrollIndicator={false}
          style={styles.aoeTypeScroller}
        >
          {Object.values(AOE_TYPES).map(type => (
            <TouchableOpacity
              key={type}
              style={[
                styles.aoeTypeButton,
                selectedAoe.type === type && styles.aoeTypeActive
              ]}
              onPress={() => onTypeChange(type)}
            >
              <Text style={styles.aoeTypeText}>
                {type.charAt(0).toUpperCase() + type.slice(1)}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
        
        <ScrollView 
          horizontal 
          showsHorizontalScrollIndicator={false}
          style={styles.aoeSizeScroller}
        >
          {AOE_SIZES[selectedAoe.type].map(size => (
            <TouchableOpacity
              key={size}
              style={[
                styles.aoeSizeButton,
                selectedAoe.size === size && styles.aoeSizeActive
              ]}
              onPress={() => onSizeChange(size)}
            >
              <Text style={styles.aoeSizeText}>{size}ft</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </>
    )}
  </View>
));
